<template><div class="app-container"><div class="workspace-heading"><div><h2>存证任务</h2><p>业务已独立提交。存证失败可重试，不会重复确认捐赠或扣减退款。</p></div><el-button @click="load">刷新</el-button></div><el-card shadow="never"><el-table :data="list" v-loading="loading" stripe><el-table-column prop="taskId" label="任务" width="80" /><el-table-column prop="eventKey" label="事件键" min-width="220" show-overflow-tooltip /><el-table-column prop="chainSource" label="来源" width="95" /><el-table-column label="状态" width="180"><template #default="{row}">{{ label(row.status) }}</template></el-table-column><el-table-column prop="retryCount" label="重试次数" width="100" /><el-table-column prop="durationMs" label="提交耗时(ms)" width="130" /><el-table-column prop="errorMsg" label="最近错误" min-width="200" /><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="row.status!=='SUBMITTED'" link type="primary" :loading="busy===row.taskId" @click="retry(row)">安排重试</el-button></template></el-table-column></el-table><div class="table-pagination"><el-pagination v-model:current-page="query.current" :page-size="query.size" :total="total" layout="total,prev,pager,next" @current-change="load" /></div></el-card></div></template>
<script>
import { listTasks,retryTask,statusLabel } from '@/api/finance'
export default {name:'EvidenceTasks',data:()=>({list:[],total:0,loading:false,busy:null,query:{current:1,size:20}}),created(){this.load()},methods:{label:statusLabel,async load(){this.loading=true;try{const r=await listTasks(this.query);this.list=r.data.records;this.total=r.data.total}finally{this.loading=false}},async retry(row){this.busy=row.taskId;try{await retryTask(row.taskId);this.$message.success('已安排重试，稍后刷新查看结果');await this.load()}finally{this.busy=null}}}}
</script>
